package org.sleepwell.app;
import android.app.*;import android.os.Bundle;
/** Shared real clock UI. Closing/recreation never confirms a snooze. */
final class SnoozeUntilDialog {
 static Dialog show(Activity activity,SnoozeUntil offer,SnoozeUntil.Port port){Dialog[] own={null};String detail="Today · "+offer.date+" · "+offer.offered.zone+"\nUp to "+SnoozeBudget.label(Math.min(SnoozePolicy.minutes(offer.offered.base,offer.offered.shorten,offer.offered.used)*60000L,SnoozeBudget.remaining(offer.offered.totalMinutes,offer.offered.spentMillis)))+" from confirmation. No next-day rollover.";Dialog dialog=SleepPicker.time(activity,"Snooze until",offer.initialMinute(),n->{},minute->{Dialog visible=own[0];if(visible==null||!visible.isShowing()||activity.isDestroyed()||activity.isFinishing()||!visible.getWindow().getDecorView().hasWindowFocus())return "Return to this clock before confirming.";return offer.confirm(minute,port);},detail,"Snooze until this time");own[0]=dialog;Application application=activity.getApplication();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityPaused(Activity a){if(a==activity)dialog.dismiss();}public void onActivityDestroyed(Activity a){if(a==activity)dialog.dismiss();}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}};application.registerActivityLifecycleCallbacks(lifecycle);dialog.setOnDismissListener(ignored->{offer.cancel();application.unregisterActivityLifecycleCallbacks(lifecycle);});return dialog;}
 private SnoozeUntilDialog(){}
}
